Here is the commit message:
netfilter: nft_set_rbtree: check for partial overlaps in
 anonymous sets

Userspace provides an optimized representation in case intervals are
adjacent, where the end element is omitted.

The existing partial overlap detection logic skips anonymous set checks
on start elements for this reason.

However, it is possible to add intervals that overlap to this anonymous
where two start elements with the same, eg. A-B, A-C where C < B.

      start     end
	A        B
      start  end
        A     C

Restore the check on overlapping start elements to report an overlap.

Fixes: c9e6978e2725 ("netfilter: nft_set_rbtree: Switch to node list walk for overlap detection")
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>
Signed-off-by: Florian Westphal <fw@strlen.de>

Here is the root cause:
The partial overlap detection in `__nft_rbtree_insert` was completely skipped for anonymous sets when two start elements are adjacent, allowing insertion of overlapping intervals (e.g., A-B and A-C with C < B) because the missing check did not verify if the preceding element is an end interval that would indicate an overlap.

Here is the patch:

+/* Only for anonymous sets which do not allow updates, all element are active. */
+static struct nft_rbtree_elem *nft_rbtree_prev_active(struct nft_rbtree_elem *rbe)
+{
+	struct rb_node *node;
+
+	node = rb_prev(&rbe->node);
+	if (!node)
+		return NULL;
+
+	return rb_entry(node, struct nft_rbtree_elem, node);
+}
+
 static int __nft_rbtree_insert(const struct net *net, const struct nft_set *set,
 			       struct nft_rbtree_elem *new,
 			       struct nft_elem_priv **elem_priv)
 {
-	struct nft_rbtree_elem *rbe, *rbe_le = NULL, *rbe_ge = NULL;
+	struct nft_rbtree_elem *rbe, *rbe_le = NULL, *rbe_ge = NULL, *rbe_prev;
 	struct rb_node *node, *next, *parent, **p, *first = NULL;
 	struct nft_rbtree *priv = nft_set_priv(set);
 	u8 cur_genmask = nft_genmask_cur(net);
 	u8 genmask = nft_genmask_next(net);
 	u64 tstamp = nft_net_tstamp(net);
 	int d;

 	/* Descend the tree to search for an existing element greater than the
 	 * key value to insert that is greater than the new element. This is the
 	 * first element to walk the ordered elements to find possible overlap.
 	 */
 	parent = NULL;
 	p = &priv->root.rb_node;
 	while (*p != NULL) {
 		parent = *p;
 		rbe = rb_entry(parent, struct nft_rbtree_elem, node);
 		d = nft_rbtree_cmp(set, rbe, new);

 		if (d < 0) {
 			p = &parent->rb_left;
 		} else if (d > 0) {
 			if (!first ||
 			    nft_rbtree_update_first(set, rbe, first))
 				first = &rbe->node;

 			p = &parent->rb_right;
 		} else {
 			if (nft_rbtree_interval_end(rbe))
 				p = &parent->rb_left;
 			else
 				p = &parent->rb_right;
 		}
 	}

 	if (!first)
 		first = rb_first(&priv->root);

 	/* Detect overlap by going through the list of valid tree nodes.
 	 * Values stored in the tree are in reversed order, starting from
 	 * highest to lowest value.
 	 */
 	for (node = first; node != NULL; node = next) {
 		next = rb_next(node);

 		rbe = rb_entry(node, struct nft_rbtree_elem, node);

 		if (!nft_set_elem_active(&rbe->ext, genmask))
 			continue;

 		/* perform garbage collection to avoid bogus overlap reports
 		 * but skip new elements in this transaction.
 		 */
 		if (__nft_set_elem_expired(&rbe->ext, tstamp) &&
 		    nft_set_elem_active(&rbe->ext, cur_genmask)) {
 			const struct nft_rbtree_elem *removed_end;

 			removed_end = nft_rbtree_gc_elem(set, priv, rbe);
 			if (IS_ERR(removed_end))
 				return PTR_ERR(removed_end);

 			if (removed_end == rbe_le || removed_end == rbe_ge)
 				return -EAGAIN;

 			continue;
 		}

 		d = nft_rbtree_cmp(set, rbe, new);
 		if (d == 0) {
 			/* Matching end element: no need to look for an
 			 * overlapping greater or equal element.
 			 */
 			if (nft_rbtree_interval_end(rbe)) {
 				rbe_le = rbe;
 				break;
 			}

 			/* first element that is greater or equal to key value. */
 			if (!rbe_ge) {
 				rbe_ge = rbe;
 				continue;
 			}

 			/* this is a closer more or equal element, update it. */
 			if (nft_rbtree_cmp(set, rbe_ge, new) != 0) {
 				rbe_ge = rbe;
 				continue;
 			}

 			/* element is equal to key value, make sure flags are
 			 * the same, an existing more or equal start element
 			 * must not be replaced by more or equal end element.
 			 */
 			if ((nft_rbtree_interval_start(new) &&
 			     nft_rbtree_interval_start(rbe_ge)) ||
 			    (nft_rbtree_interval_end(new) &&
 			     nft_rbtree_interval_end(rbe_ge))) {
 				rbe_ge = rbe;
 				continue;
 			}
 		} else if (d > 0) {
 			/* annotate element greater than the new element. */
 			rbe_ge = rbe;
 			continue;
 		} else if (d < 0) {
 			/* annotate element less than the new element. */
 			rbe_le = rbe;
 			break;
 		}
 	}

 	/* - new start element matching existing start element: full overlap
 	 *   reported as -EEXIST, cleared by caller if NLM_F_EXCL is not given.
 	 */
 	if (rbe_ge && !nft_rbtree_cmp(set, new, rbe_ge) &&
 	    nft_rbtree_interval_start(rbe_ge) == nft_rbtree_interval_start(new)) {
 		*elem_priv = &rbe_ge->priv;
 		return -EEXIST;
 	}

 	/* - new end element matching existing end element: full overlap
 	 *   reported as -EEXIST, cleared by caller if NLM_F_EXCL is not given.
 	 */
 	if (rbe_le && !nft_rbtree_cmp(set, new, rbe_le) &&
 	    nft_rbtree_interval_end(rbe_le) == nft_rbtree_interval_end(new)) {
 		/* - ignore null interval, otherwise NLM_F_CREATE bogusly
 		 *   reports EEXIST.
 		 */
 		if (nft_rbtree_interval_null(set, new))
 			return -ECANCELED;

 		*elem_priv = &rbe_le->priv;
 		return -EEXIST;
 	}

 	/* - new start element with existing closest, less or equal key value
 	 *   being a start element: partial overlap, reported as -ENOTEMPTY.
 	 *   Anonymous sets allow for two consecutive start element since they
-	 *   are constant, skip them to avoid bogus overlap reports.
+	 *   are constant, but validate that this new start element does not
+	 *   sit in between an existing start and end elements: partial overlap,
+	 *   reported as -ENOTEMPTY.
 	 */
-	if (!nft_set_is_anonymous(set) && rbe_le &&
-	    nft_rbtree_interval_start(rbe_le) && nft_rbtree_interval_start(new))
-		return -ENOTEMPTY;
+	if (rbe_le &&
+	    nft_rbtree_interval_start(rbe_le) && nft_rbtree_interval_start(new)) {
+		if (!nft_set_is_anonymous(set))
+			return -ENOTEMPTY;
+
+		rbe_prev = nft_rbtree_prev_active(rbe_le);
+		if (rbe_prev && nft_rbtree_interval_end(rbe_prev))
+			return -ENOTEMPTY;
+	}

 	/* - new end element with existing closest, less or equal key value
 	 *   being a end element: partial overlap, reported as -ENOTEMPTY.
 	 */
 	if (rbe_le &&
 	    nft_rbtree_interval_end(rbe_le) && nft_rbtree_interval_end(new))
 		return -ENOTEMPTY;

 	/* - new end element with existing closest, greater or equal key value
 	 *   being an end element: partial overlap, reported as -ENOTEMPTY
 	 */
 	if (rbe_ge &&
 	    nft_rbtree_interval_end(rbe_ge) && nft_rbtree_interval_end(new))
 		return -ENOTEMPTY;

 	/* Accepted element: pick insertion point depending on key value */
 	parent = NULL;
 	p = &priv->root.rb_node;
 	while (*p != NULL) {
 		parent = *p;
 		rbe = rb_entry(parent, struct nft_rbtree_elem, node);
 		d = nft_rbtree_cmp(set, rbe, new);

 		if (d < 0)
 			p = &parent->rb_left;
 		else if (d > 0)
 			p = &parent->rb_right;
 		else if (nft_rbtree_interval_end(rbe))
 			p = &parent->rb_left;
 		else
 			p = &parent->rb_right;
 	}

 	rb_link_node_rcu(&new->node, parent, p);
 	rb_insert_color(&new->node, &priv->root);
 	return 0;
 }



